def score(d, v, robust=False):
    keep = np.ones(len(d), bool)
    if robust:
        for _ in range(8):
            w = np.linalg.lstsq(d[keep], v[keep], rcond=None)[0]
            r = np.linalg.norm(v - d @ w, axis=1)
            keep = np.argsort(r)[:45]
    a = d[keep]
    w = np.linalg.lstsq(a, v[keep], rcond=None)[0]
    e = v[keep] - a @ w
    h = np.sum(a * np.linalg.pinv(a).T, axis=1)
